DROP TABLE IF EXISTS images;
CREATE TABLE images (
  date INTEGER NOT NULL,
  locale TEXT NOT NULL DEFAULT 'zh-CN',
  url TEXT NOT NULL,
  urlbase TEXT NOT NULL,
  copyright TEXT DEFAULT '',
  copyright_link TEXT DEFAULT '',
  title TEXT DEFAULT '',
  imgdetail TEXT DEFAULT '',
  created_at TEXT DEFAULT '',
  updated_at TEXT DEFAULT '',
  PRIMARY KEY (date, locale)
);
CREATE INDEX IF NOT EXISTS idx_images_locale_date ON images(locale, date);
在博尼法乔，城堡是不可错过的地标。这座城堡最初建于9世纪，后来不断扩建。如今，游客可以漫步在宁静的街道、古老的军事建筑与鹅卵石铺就的小巷中。周边还有“海洋公墓”、阿拉贡国王台阶，以及如今作为小型博物馆开放的旗帜堡垒等景点，等待人们前来探索。</p>', '2025-08-20 00:00:01', '2026-03-09 09:14:20');
常被誉为华盛顿州最宁静的自然奇观之一，帕卢斯地区标志性的起伏山丘源于一段古老而引人入胜的地质故事。这些类似沙丘的山丘并非由河流或地壳运动塑造，而是由来自干旱西南部的风吹尘土和细粒淤泥（即“黄土”）在数千年中逐渐堆积而成。在冰河时代，来自加拿大的冰川将岩石磨成细小的“冰川粉”，这些粉尘流入史前时期的冰川密苏拉湖。当冰坝决堤时，洪水席卷了华盛顿州东部，留下层层淤泥。随后，主导风将这些尘埃带到该地区，沉积成我们今天所见的丘陵。</p>', '2025-08-22 00:00:01', '2025-08-29 00:00:01');
